from pathlib import Path
p=Path('work/pocket-research/interaction-tests.cjs');s=p.read_text(encoding='utf-8');i=s.index('fs.writeFileSync')
s=s[:i]+'''
const named=name=>{const c=cards.find(c=>c.name===name&&c.program);assert(c,name);return c;};
function equip(s,p,name,index=0){const c=named(name);s.players[p.id].hand.push({id:c.id,key:900});s=R.apply(s,{type:'trainer',player:p.id,card:900});assert.equal(s.prompt.kind,'pokemon');return R.apply(s,{type:'choice',player:p.id,value:{player:p.id,key:index===0?p.active.key:p.bench[index-1].key}});}
test('Tool selection attaches to one eligible Pokemon and rejects a second Tool',()=>{let{s,p}=fixture();s=equip(s,p,'Giant Cape');assert.equal(R.maximumHp(s.players[p.id].active),get('a1-001').hp+20);assert.equal(s.players[p.id].active.tool.key,900);s.players[p.id].hand.push({id:named('Rocky Helmet').id,key:901});s=R.apply(s,{type:'trainer',player:p.id,card:901});assert(!s.prompt.options.some(x=>x.key===201));const before=JSON.stringify(s);assert.throws(()=>R.apply(s,{type:'choice',player:p.id,value:{player:p.id,key:201}}));assert.equal(JSON.stringify(s),before);});
test('Conditional HP Tools apply only to their printed type and evolution stage',()=>{let{s,p}=fixture();s=equip(s,p,'Leaf Cape');assert.equal(R.maximumHp(s.players[p.id].active),get('a1-001').hp+30);s.players[p.id].active.stack=[ref('a1-033',201)];assert.equal(R.maximumHp(s.players[p.id].active),get('a1-033').hp);});
test('Retreat modifiers sum and the shared UI cost query matches payment',()=>{let{s,p}=fixture();p.effects=[{kind:'retreat',amount:1,expires:5},{kind:'retreat',amount:1,expires:5}];assert.equal(R.retreatCost(s,p),Math.max(0,get('a1-001').retreat-2));s=equip(s,p,'Small Balloon');assert.equal(R.retreatCost(s,s.players[p.id]),Math.max(0,get('a1-001').retreat-3));s=R.apply(s,{type:'retreat',player:p.id,target:202,energy:[]});assert.equal(s.players[p.id].active.key,202);});
test('Rocky Helmet only retaliates when its holder is Active and damaged',()=>{let{s,p,o}=fixture();s=equip(s,o,'Rocky Helmet');s=attack(s);assert.equal(s.players[p.id].active.damage,20);let f=fixture();s=equip(f.s,f.o,'Rocky Helmet',1);s=attack(s);assert.equal(s.players[f.p.id].active.damage,0);});
test('Clear Veil blocks attack effects while allowing printed damage',()=>{const c=pick(c=>c.attacks.some(a=>a.text==="Your opponent's Active Pokémon is now Poisoned."));let{s,p,o}=fixture(c.sourceId);s=equip(s,o,'Clear Veil');s=attack(s,c.attacks.findIndex(a=>a.text==="Your opponent's Active Pokémon is now Poisoned."));assert(!s.players[o.id].active.conditions.includes('Poisoned'));assert(s.players[o.id].active.damage>0);});
test('Protective Poncho prevents opposing Ability damage on the Bench',()=>{let{s,p,o}=fixture();p.bench[0]=slot('a1-089',202);s=equip(s,o,'Protective Poncho',1);s=R.apply(s,{type:'ability',player:p.id,slot:1});s=R.apply(s,{type:'choice',player:p.id,value:{player:o.id,key:302}});assert.equal(s.players[o.id].bench[0].damage,0);});
test('Lum Berry cures conditions, discards once, and preserves the Pokemon',()=>{let{s,p}=fixture();p.active.conditions=['Poisoned','Confused'];s=equip(s,p,'Lum Berry');s=R.apply(s,{type:'pass',player:p.id});assert.equal(s.players[p.id].active.damage,0);assert.deepEqual(s.players[p.id].active.conditions,[]);assert.equal(s.players[p.id].active.tool,null);assert(s.players[p.id].discard.some(x=>x.key===900));});
test('Sitrus Berry heals at half HP and discards, with a healthy negative control',()=>{let{s,p}=fixture();p.active.damage=40;s=equip(s,p,'Sitrus Berry');s=R.apply(s,{type:'pass',player:p.id});assert.equal(s.players[p.id].active.damage,10);assert.equal(s.players[p.id].active.tool,null);let f=fixture();s=equip(f.s,f.p,'Sitrus Berry');s=R.apply(s,{type:'pass',player:f.p.id});assert(s.players[f.p.id].active.tool);});
''' +s[i:];p.write_text(s,encoding='utf-8')
